#[test]
fn unit_metadata() {
    let info = Jerk::<f64>::INFO;
    assert_eq!(info.name, "Jerk");
    assert_eq!(info.units.len(), JerkUnit::ALL.len());
    for (&unit, unit_info) in JerkUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, JerkUnit::MeterPerSecondCubed.info());
}

