#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [Jerk; 11] = [
        Jerk::const_new(1234.5, JerkUnit::MeterPerSecondCubed),
        Jerk::const_new(1234.5, JerkUnit::NanometerPerSecondCubed),
        Jerk::const_new(1234.5, JerkUnit::MicrometerPerSecondCubed),
        Jerk::const_new(1234.5, JerkUnit::MillimeterPerSecondCubed),
        Jerk::const_new(1234.5, JerkUnit::CentimeterPerSecondCubed),
        Jerk::const_new(1234.5, JerkUnit::DecimeterPerSecondCubed),
        Jerk::const_new(1234.5, JerkUnit::KilometerPerSecondCubed),
        Jerk::const_new(1234.5, JerkUnit::InchPerSecondCubed),
        Jerk::const_new(1234.5, JerkUnit::FootPerSecondCubed),
        Jerk::const_new(1234.5, JerkUnit::StandardGravitiesPerSecond),
        Jerk::const_new(1234.5, JerkUnit::MillistandardGravitiesPerSecond),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(JerkUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            Jerk::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in JerkUnit::ALL {
            assert_eq!(
                Jerk::const_new(v, unit).as_base().to_bits(),
                Jerk::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Jerk::from_base(v);
        let auto = q.auto_unit();
        assert_close(Jerk::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in JerkUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Jerk::from_base(0.0).auto_unit().unit,
        JerkUnit::MeterPerSecondCubed
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "m/s³".parse::<JerkUnit>(),
        Ok(JerkUnit::MeterPerSecondCubed)
    );
    assert_eq!(
        format!("2.5 {}", "m/s³").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::MeterPerSecondCubed))
    );
    assert_eq!(
        "nm/s³".parse::<JerkUnit>(),
        Ok(JerkUnit::NanometerPerSecondCubed)
    );
    assert_eq!(
        format!("2.5 {}", "nm/s³").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::NanometerPerSecondCubed))
    );
    assert_eq!(
        "µm/s³".parse::<JerkUnit>(),
        Ok(JerkUnit::MicrometerPerSecondCubed)
    );
    assert_eq!(
        format!("2.5 {}", "µm/s³").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::MicrometerPerSecondCubed))
    );
    assert_eq!(
        "mm/s³".parse::<JerkUnit>(),
        Ok(JerkUnit::MillimeterPerSecondCubed)
    );
    assert_eq!(
        format!("2.5 {}", "mm/s³").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::MillimeterPerSecondCubed))
    );
    assert_eq!(
        "cm/s³".parse::<JerkUnit>(),
        Ok(JerkUnit::CentimeterPerSecondCubed)
    );
    assert_eq!(
        format!("2.5 {}", "cm/s³").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::CentimeterPerSecondCubed))
    );
    assert_eq!(
        "dm/s³".parse::<JerkUnit>(),
        Ok(JerkUnit::DecimeterPerSecondCubed)
    );
    assert_eq!(
        format!("2.5 {}", "dm/s³").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::DecimeterPerSecondCubed))
    );
    assert_eq!(
        "km/s³".parse::<JerkUnit>(),
        Ok(JerkUnit::KilometerPerSecondCubed)
    );
    assert_eq!(
        format!("2.5 {}", "km/s³").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::KilometerPerSecondCubed))
    );
    assert_eq!(
        "in/s³".parse::<JerkUnit>(),
        Ok(JerkUnit::InchPerSecondCubed)
    );
    assert_eq!(
        format!("2.5 {}", "in/s³").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::InchPerSecondCubed))
    );
    assert_eq!(
        "ft/s³".parse::<JerkUnit>(),
        Ok(JerkUnit::FootPerSecondCubed)
    );
    assert_eq!(
        format!("2.5 {}", "ft/s³").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::FootPerSecondCubed))
    );
    assert_eq!(
        "g/s".parse::<JerkUnit>(),
        Ok(JerkUnit::StandardGravitiesPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "g/s").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::StandardGravitiesPerSecond))
    );
    assert_eq!(
        "mg/s".parse::<JerkUnit>(),
        Ok(JerkUnit::MillistandardGravitiesPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "mg/s").parse::<Jerk>(),
        Ok(Jerk::new(2.5, JerkUnit::MillistandardGravitiesPerSecond))
    );
    assert_eq!("1 not-a-unit".parse::<Jerk>(), Err(ParseError::UnknownUnit));
}

